"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[257],{4257:(n,t,e)=>{e.d(t,{F:()=>o,a:()=>c});var i=e(844);let h={en:i.Kq.map(n=>"".concat(n.name,". ").concat(n.purpose.en)),vi:i.Kq.map(n=>"".concat(n.name,". ").concat(n.purpose.vi))},o={title:{en:"Privacy Policy",vi:"Ch\xednh s\xe1ch quyền ri\xeang tư"},summary:{en:"This policy covers the ".concat(i.C3," VPN app and this website. It lists every category of data we store, why we store it, and how long we keep it."),vi:"Ch\xednh s\xe1ch n\xe0y \xe1p dụng cho ứng dụng VPN ".concat(i.C3," v\xe0 website n\xe0y. Văn bản liệt k\xea từng loại dữ liệu ch\xfang t\xf4i lưu, l\xfd do lưu, v\xe0 thời gian lưu.")},updated:i.ji,sections:[{id:"data-we-store",title:{en:"Data we store",vi:"Dữ liệu ch\xfang t\xf4i lưu"},blocks:[{type:"p",text:{en:"We store the following data about you. This table is the complete list.",vi:"Ch\xfang t\xf4i lưu những dữ liệu sau đ\xe2y về bạn. Bảng n\xe0y l\xe0 danh s\xe1ch đầy đủ."}},{type:"table",headers:{en:["Data","Why we store it","How long we keep it"],vi:["Dữ liệu","L\xfd do lưu","Thời gian lưu"]},rows:[{en:["Email address","To sign you in, reset your password, and send notices about the service.","Until you delete your account."],vi:["Địa chỉ email","Để đăng nhập, đặt lại mật khẩu, v\xe0 gửi th\xf4ng b\xe1o về dịch vụ.","Đến khi bạn xo\xe1 t\xe0i khoản."]},{en:["Hashed password","To verify your sign-in. We do not store the password itself and cannot read it.","Until you delete your account."],vi:["Mật khẩu đ\xe3 băm","Để x\xe1c thực đăng nhập. Ch\xfang t\xf4i kh\xf4ng lưu mật khẩu gốc v\xe0 kh\xf4ng đọc được n\xf3.","Đến khi bạn xo\xe1 t\xe0i khoản."]},{en:["Subscription status and transaction reference","To activate your plan, handle renewals, and resolve payment disputes.","24 months after the transaction, even if you delete your account sooner."],vi:["Trạng th\xe1i g\xf3i v\xe0 m\xe3 tham chiếu giao dịch","Để k\xedch hoạt g\xf3i, xử l\xfd gia hạn, v\xe0 giải quyết tranh chấp thanh to\xe1n.","24 th\xe1ng kể từ giao dịch, kể cả khi bạn xo\xe1 t\xe0i khoản sớm hơn."]},{en:["Crash reports and basic usage analytics","To find out why the app crashed or failed to connect.","90 days."],vi:["B\xe1o c\xe1o sự cố v\xe0 số liệu sử dụng cơ bản","Để t\xecm nguy\xean nh\xe2n ứng dụng bị lỗi hoặc kh\xf4ng kết nối được.","90 ng\xe0y."]}]},{type:"note",text:{en:"Transaction references outlive account deletion. We keep them for 24 months because payment providers allow chargebacks and refund claims long after a purchase, and we need the record to answer one.",vi:"M\xe3 tham chiếu giao dịch tồn tại l\xe2u hơn việc xo\xe1 t\xe0i khoản. Ch\xfang t\xf4i giữ 24 th\xe1ng v\xec c\xe1c đơn vị thanh to\xe1n cho ph\xe9p khiếu nại v\xe0 đ\xf2i ho\xe0n tiền rất l\xe2u sau khi mua, v\xe0 ch\xfang t\xf4i cần bản ghi để trả lời khiếu nại đ\xf3."}}]},{id:"data-we-do-not-store",title:{en:"Data we do not store",vi:"Dữ liệu ch\xfang t\xf4i kh\xf4ng lưu"},blocks:[{type:"p",text:{en:"We do not create logs of what you do through the VPN tunnel. The following are not recorded on our servers:",vi:"Ch\xfang t\xf4i kh\xf4ng tạo nhật k\xfd về những g\xec bạn l\xe0m qua đường hầm VPN. Những mục sau kh\xf4ng được ghi lại tr\xean m\xe1y chủ của ch\xfang t\xf4i:"}},{type:"ul",items:{en:["Browsing history and the websites you open","DNS queries","Traffic destinations and connection metadata","Your original IP address"],vi:["Lịch sử duyệt web v\xe0 c\xe1c trang bạn mở","Truy vấn DNS","Điểm đến lưu lượng v\xe0 metadata kết nối","Địa chỉ IP gốc của bạn"]}},{type:"p",text:{en:"This applies to the VPN traffic itself. It does not extend to the account and payment data listed in the table above, which we do store.",vi:"Điều n\xe0y \xe1p dụng cho lưu lượng VPN. N\xf3 kh\xf4ng \xe1p dụng cho dữ liệu t\xe0i khoản v\xe0 thanh to\xe1n đ\xe3 liệt k\xea ở bảng tr\xean, vốn l\xe0 dữ liệu ch\xfang t\xf4i c\xf3 lưu."}}]},{id:"vpn-commitment",title:{en:"Our commitment on VPN data",vi:"Cam kết về dữ liệu VPN"},blocks:[{type:"p",text:{en:"We do not sell, use, or disclose to third parties any data arising from your use of the VPN service, for any purpose. We do not inspect, profile, or monetise your traffic, and we do not inject or modify content in it.",vi:"Ch\xfang t\xf4i kh\xf4ng b\xe1n, kh\xf4ng sử dụng v\xe0 kh\xf4ng tiết lộ cho b\xean thứ ba bất kỳ dữ liệu n\xe0o ph\xe1t sinh từ việc bạn d\xf9ng dịch vụ VPN, v\xec bất kỳ mục đ\xedch n\xe0o. Ch\xfang t\xf4i kh\xf4ng kiểm tra nội dung, kh\xf4ng lập hồ sơ h\xe0nh vi, kh\xf4ng thương mại ho\xe1 lưu lượng của bạn, v\xe0 kh\xf4ng ch\xe8n hay sửa đổi nội dung trong đ\xf3."}},{type:"p",text:{en:"We will disclose account data only where we are legally required to. Because the logs described in the previous section are never created, we cannot produce them in response to any request.",vi:"Ch\xfang t\xf4i chỉ cung cấp dữ liệu t\xe0i khoản khi ph\xe1p luật bắt buộc. V\xec c\xe1c nhật k\xfd n\xeau ở mục tr\xean kh\xf4ng bao giờ được tạo ra, ch\xfang t\xf4i kh\xf4ng thể cung cấp ch\xfang cho bất kỳ y\xeau cầu n\xe0o."}}]},{id:"third-parties",title:{en:"Third parties that receive data",vi:"B\xean thứ ba nhận dữ liệu"},blocks:[{type:"p",text:{en:"Running the service requires these providers. Each one receives only the data it needs for the purpose listed.",vi:"Việc vận h\xe0nh dịch vụ cần đến c\xe1c nh\xe0 cung cấp sau. Mỗi b\xean chỉ nhận phần dữ liệu cần thiết cho mục đ\xedch được n\xeau."}},{type:"ul",items:h},{type:"p",text:{en:"Each of these providers is required to protect your data to a standard equal to or better than the one stated in this policy. We do not share your data with advertising networks or data brokers, and we do not sell it.",vi:"Mỗi nh\xe0 cung cấp n\xeau tr\xean đều phải bảo vệ dữ liệu của bạn ở mức tương đương hoặc cao hơn mức n\xeau trong ch\xednh s\xe1ch n\xe0y. Ch\xfang t\xf4i kh\xf4ng chia sẻ dữ liệu của bạn với mạng quảng c\xe1o hay đơn vị m\xf4i giới dữ liệu, v\xe0 kh\xf4ng b\xe1n dữ liệu."}}]},{id:"security",title:{en:"How we protect data",vi:"C\xe1ch ch\xfang t\xf4i bảo vệ dữ liệu"},blocks:[{type:"p",text:{en:"All traffic between your device and our tunnel endpoint is encrypted with AES-256. Passwords are stored as salted hashes. Account data sits on access-controlled infrastructure, reachable only by the systems that need it for authentication and billing.",vi:"To\xe0n bộ lưu lượng giữa thiết bị của bạn v\xe0 điểm cuối đường hầm của ch\xfang t\xf4i được m\xe3 ho\xe1 bằng AES-256. Mật khẩu được lưu dưới dạng băm c\xf3 salt. Dữ liệu t\xe0i khoản nằm tr\xean hạ tầng c\xf3 kiểm so\xe1t truy cập, chỉ những hệ thống cần cho x\xe1c thực v\xe0 thanh to\xe1n mới chạm tới được."}},{type:"p",text:{en:"No system is immune to breach. If a breach affects your account data, we will notify you by email at the address on the account.",vi:"Kh\xf4ng hệ thống n\xe0o miễn nhiễm với sự cố bảo mật. Nếu một sự cố ảnh hưởng đến dữ liệu t\xe0i khoản của bạn, ch\xfang t\xf4i sẽ th\xf4ng b\xe1o qua email tới địa chỉ đăng k\xfd tr\xean t\xe0i khoản."}}]},{id:"deletion",title:{en:"Deleting your account",vi:"Xo\xe1 t\xe0i khoản của bạn"},blocks:[{type:"p",text:{en:"You can delete your account yourself at any time, either from the Account tab in the app or at ".concat(i.Sc," in a browser. Both take effect immediately and neither needs our approval. If you cannot sign in, email ").concat(i.Te," from the address on the account and we will delete it within ").concat(i.CW," working days."),vi:"Bạn c\xf3 thể tự xo\xe1 t\xe0i khoản bất cứ l\xfac n\xe0o, tại tab T\xe0i khoản trong ứng dụng hoặc tại ".concat(i.Sc," tr\xean tr\xecnh duyệt. Cả hai c\xe1ch đều c\xf3 hiệu lực ngay v\xe0 kh\xf4ng cần ch\xfang t\xf4i ph\xea duyệt. Nếu bạn kh\xf4ng đăng nhập được, h\xe3y gửi email tới ").concat(i.Te," từ ch\xednh địa chỉ đăng k\xfd tr\xean t\xe0i khoản, ch\xfang t\xf4i sẽ xo\xe1 trong v\xf2ng ").concat(i.CW," ng\xe0y l\xe0m việc.")}},{type:"p",text:{en:"Deletion removes your email address, your hashed password, and your subscription status. Transaction references are kept for the 24 months described above. Accounts with no sign-in for 90 days are deleted automatically on the same terms.",vi:"Việc xo\xe1 sẽ gỡ bỏ địa chỉ email, mật khẩu đ\xe3 băm v\xe0 trạng th\xe1i g\xf3i của bạn. M\xe3 tham chiếu giao dịch được giữ trong 24 th\xe1ng như m\xf4 tả ở tr\xean. T\xe0i khoản kh\xf4ng đăng nhập trong 90 ng\xe0y sẽ bị xo\xe1 tự động theo c\xf9ng điều kiện."}},{type:"note",text:{en:"Deleting your account does not cancel a subscription bought through the App Store or Google Play. Cancel it in your store account first, otherwise billing continues.",vi:"Xo\xe1 t\xe0i khoản kh\xf4ng huỷ g\xf3i đ\xe3 mua qua App Store hoặc Google Play. H\xe3y huỷ g\xf3i trong t\xe0i khoản cửa h\xe0ng của bạn trước, nếu kh\xf4ng việc thanh to\xe1n vẫn tiếp tục."}}]},{id:"your-rights",title:{en:"Your rights",vi:"Quyền của bạn"},blocks:[{type:"p",text:{en:"Whatever country you are in, you can ask us to do any of the following:",vi:"D\xf9 bạn ở quốc gia n\xe0o, bạn đều c\xf3 thể y\xeau cầu ch\xfang t\xf4i:"}},{type:"ul",items:{en:["Send you a copy of the account data we hold about you","Correct the email address on your account","Delete your account and its data","Stop sending you service notices that are not required for billing","Withdraw consent for crash reporting and analytics"],vi:["Gửi cho bạn bản sao dữ liệu t\xe0i khoản m\xe0 ch\xfang t\xf4i đang giữ","Sửa địa chỉ email tr\xean t\xe0i khoản của bạn","Xo\xe1 t\xe0i khoản v\xe0 dữ liệu của t\xe0i khoản đ\xf3","Ngừng gửi th\xf4ng b\xe1o dịch vụ kh\xf4ng bắt buộc cho việc thanh to\xe1n","R\xfat lại đồng \xfd cho việc thu thập b\xe1o c\xe1o sự cố v\xe0 số liệu sử dụng"]}},{type:"p",text:{en:"Email ".concat(i.Te," from the address on the account. We reply within ").concat(i.CW," working days. We do not charge for these requests and we will not restrict your service for making one."),vi:"H\xe3y gửi email tới ".concat(i.Te," từ địa chỉ đăng k\xfd tr\xean t\xe0i khoản. Ch\xfang t\xf4i trả lời trong ").concat(i.CW," ng\xe0y l\xe0m việc. Ch\xfang t\xf4i kh\xf4ng thu ph\xed cho c\xe1c y\xeau cầu n\xe0y v\xe0 kh\xf4ng hạn chế dịch vụ của bạn v\xec bạn gửi y\xeau cầu.")}}]},{id:"children",title:{en:"Children",vi:"Trẻ em"},blocks:[{type:"p",text:{en:"".concat(i.C3," is not directed at children under 13, and we do not knowingly create accounts for them. If you believe a child under 13 has an account, email ").concat(i.Te," and we will delete it."),vi:"".concat(i.C3," kh\xf4ng hướng tới trẻ em dưới 13 tuổi, v\xe0 ch\xfang t\xf4i kh\xf4ng cố \xfd tạo t\xe0i khoản cho trẻ em dưới 13 tuổi. Nếu bạn cho rằng một trẻ dưới 13 tuổi đang c\xf3 t\xe0i khoản, h\xe3y gửi email tới ").concat(i.Te," v\xe0 ch\xfang t\xf4i sẽ xo\xe1 t\xe0i khoản đ\xf3.")}}]},{id:"international",title:{en:"Where data is processed",vi:"Nơi dữ liệu được xử l\xfd"},blocks:[{type:"p",text:{en:"Our VPN servers run in several countries so that you can choose a location. Account data may be processed in any country where we or the providers listed above operate. Wherever it is processed, the protections in this policy apply.",vi:"M\xe1y chủ VPN của ch\xfang t\xf4i đặt tại nhiều quốc gia để bạn c\xf3 thể chọn vị tr\xed. Dữ liệu t\xe0i khoản c\xf3 thể được xử l\xfd tại bất kỳ quốc gia n\xe0o nơi ch\xfang t\xf4i hoặc c\xe1c nh\xe0 cung cấp n\xeau tr\xean hoạt động. D\xf9 được xử l\xfd ở đ\xe2u, c\xe1c biện ph\xe1p bảo vệ trong ch\xednh s\xe1ch n\xe0y vẫn được \xe1p dụng."}}]},{id:"changes",title:{en:"Changes to this policy",vi:"Thay đổi ch\xednh s\xe1ch"},blocks:[{type:"p",text:{en:"When we change this policy we update the effective date at the top of the page. If a change affects what we collect or who receives it, we email registered users before it takes effect.",vi:"Khi thay đổi ch\xednh s\xe1ch n\xe0y, ch\xfang t\xf4i cập nhật ng\xe0y hiệu lực ở đầu trang. Nếu thay đổi ảnh hưởng đến dữ liệu ch\xfang t\xf4i thu thập hoặc b\xean nhận dữ liệu, ch\xfang t\xf4i sẽ gửi email cho người d\xf9ng đ\xe3 đăng k\xfd trước khi thay đổi c\xf3 hiệu lực."}}]}]},c={title:{en:"Terms of Service",vi:"Điều khoản sử dụng"},summary:{en:"These terms govern your use of the ".concat(i.C3," VPN service. They cover what you may and may not do with it, how payment works, and when we can suspend an account."),vi:"Điều khoản n\xe0y điều chỉnh việc bạn sử dụng dịch vụ VPN ".concat(i.C3,". Văn bản n\xeau bạn được v\xe0 kh\xf4ng được l\xe0m g\xec, c\xe1ch thanh to\xe1n hoạt động, v\xe0 khi n\xe0o ch\xfang t\xf4i c\xf3 thể kho\xe1 t\xe0i khoản.")},updated:i.ji,sections:[{id:"agreement",title:{en:"Agreement",vi:"Chấp thuận điều khoản"},blocks:[{type:"p",text:{en:"By creating an account or using the service, you accept these terms. If you do not accept them, do not use the service.",vi:"Khi tạo t\xe0i khoản hoặc sử dụng dịch vụ, bạn chấp nhận c\xe1c điều khoản n\xe0y. Nếu bạn kh\xf4ng chấp nhận, vui l\xf2ng kh\xf4ng sử dụng dịch vụ."}},{type:"p",text:{en:"You must be at least 13 years old to hold an account.",vi:"Bạn phải từ 13 tuổi trở l\xean để c\xf3 t\xe0i khoản."}}]},{id:"lawful-use",title:{en:"Lawful use only",vi:"Chỉ sử dụng hợp ph\xe1p"},blocks:[{type:"p",text:{en:"Use the service only for lawful purposes. You must not use it to:",vi:"Chỉ sử dụng dịch vụ cho mục đ\xedch hợp ph\xe1p. Bạn kh\xf4ng được d\xf9ng dịch vụ để:"}},{type:"ul",items:{en:["Break any law that applies to you","Distribute malware or spam, or run network attacks including DDoS","Infringe copyright or other rights of third parties","Gain unauthorised access to systems or data"],vi:["Vi phạm ph\xe1p luật \xe1p dụng với bạn","Ph\xe1t t\xe1n m\xe3 độc hoặc thư r\xe1c, hoặc thực hiện tấn c\xf4ng mạng bao gồm DDoS","X\xe2m phạm bản quyền hoặc quyền kh\xe1c của b\xean thứ ba","Truy cập tr\xe1i ph\xe9p v\xe0o hệ thống hoặc dữ liệu"]}}]},{id:"your-account",title:{en:"Your account",vi:"T\xe0i khoản của bạn"},blocks:[{type:"p",text:{en:"Keep your password to yourself. You are responsible for activity carried out through your account. Tell us at once if you think someone else has access to it.",vi:"H\xe3y giữ k\xedn mật khẩu của bạn. Bạn chịu tr\xe1ch nhiệm cho hoạt động diễn ra qua t\xe0i khoản của m\xecnh. H\xe3y b\xe1o ngay cho ch\xfang t\xf4i nếu bạn cho rằng người kh\xe1c đang truy cập được t\xe0i khoản đ\xf3."}},{type:"p",text:{en:"One account is for one person. Do not share, resell, or sublicense access without our written permission.",vi:"Một t\xe0i khoản d\xe0nh cho một người. Kh\xf4ng chia sẻ, b\xe1n lại hoặc cấp quyền sử dụng lại khi chưa c\xf3 sự đồng \xfd bằng văn bản của ch\xfang t\xf4i."}}]},{id:"payment",title:{en:"Payment and renewal",vi:"Thanh to\xe1n v\xe0 gia hạn"},blocks:[{type:"p",text:{en:"Subscriptions are sold through the App Store and Google Play. Those stores take the payment, apply their own currency and tax rules, and manage renewals.",vi:"C\xe1c g\xf3i dịch vụ được b\xe1n qua App Store v\xe0 Google Play. C\xe1c cửa h\xe0ng n\xe0y thu tiền, \xe1p dụng quy định về tiền tệ v\xe0 thuế của họ, v\xe0 quản l\xfd việc gia hạn."}},{type:"p",text:{en:"Subscriptions renew automatically until you cancel. Cancel in your App Store or Google Play account settings, not in our app. Cancelling stops the next renewal and leaves your access running until the end of the period you already paid for.",vi:"C\xe1c g\xf3i tự động gia hạn cho đến khi bạn huỷ. H\xe3y huỷ trong phần c\xe0i đặt t\xe0i khoản App Store hoặc Google Play, kh\xf4ng phải trong ứng dụng của ch\xfang t\xf4i. Việc huỷ sẽ dừng lần gia hạn kế tiếp v\xe0 bạn vẫn d\xf9ng được đến hết chu kỳ đ\xe3 thanh to\xe1n."}}]},{id:"refunds",title:{en:"Refunds",vi:"Ho\xe0n tiền"},blocks:[{type:"p",text:{en:"Refunds for purchases made through the App Store or Google Play are handled by those stores under their own refund policies. Request a refund there first, because we cannot reverse a charge we did not process.",vi:"Việc ho\xe0n tiền cho c\xe1c giao dịch qua App Store hoặc Google Play do ch\xednh c\xe1c cửa h\xe0ng đ\xf3 xử l\xfd theo ch\xednh s\xe1ch ho\xe0n tiền của họ. H\xe3y y\xeau cầu ho\xe0n tiền ở đ\xf3 trước, v\xec ch\xfang t\xf4i kh\xf4ng thể ho\xe0n lại khoản thu m\xe0 ch\xfang t\xf4i kh\xf4ng trực tiếp xử l\xfd."}},{type:"p",text:{en:"Where we do process a payment directly, we refund it if the service was charged but never activated because of a fault on our side, or if you were charged the wrong amount. We do not refund a plan that has been activated and used.",vi:"Với c\xe1c khoản thanh to\xe1n ch\xfang t\xf4i trực tiếp xử l\xfd, ch\xfang t\xf4i ho\xe0n tiền nếu dịch vụ đ\xe3 bị thu tiền nhưng kh\xf4ng được k\xedch hoạt do lỗi từ ph\xeda ch\xfang t\xf4i, hoặc nếu bạn bị thu sai số tiền. Ch\xfang t\xf4i kh\xf4ng ho\xe0n tiền cho g\xf3i đ\xe3 được k\xedch hoạt v\xe0 đ\xe3 sử dụng."}}]},{id:"suspension",title:{en:"Suspension and termination",vi:"Kho\xe1 v\xe0 chấm dứt t\xe0i khoản"},blocks:[{type:"p",text:{en:"We may suspend or close an account that breaches these terms, or that is being used in a way that damages the service or other users. Typical reasons are:",vi:"Ch\xfang t\xf4i c\xf3 thể kho\xe1 hoặc đ\xf3ng t\xe0i khoản vi phạm điều khoản n\xe0y, hoặc t\xe0i khoản đang được d\xf9ng theo c\xe1ch g\xe2y hại cho dịch vụ hoặc người d\xf9ng kh\xe1c. C\xe1c l\xfd do thường gặp:"}},{type:"ul",items:{en:["Network attacks, spam, or malware distribution","Payment fraud, chargeback abuse, or stolen payment methods","Reselling access, or sharing one account across many people","Tampering with the app, such as patching, injection, or dumping data"],vi:["Tấn c\xf4ng mạng, ph\xe1t t\xe1n thư r\xe1c hoặc m\xe3 độc","Gian lận thanh to\xe1n, lạm dụng chargeback, hoặc d\xf9ng phương thức thanh to\xe1n bị đ\xe1nh cắp","B\xe1n lại quyền truy cập, hoặc d\xf9ng chung một t\xe0i khoản cho nhiều người","Can thiệp v\xe0o ứng dụng, v\xed dụ v\xe1, ch\xe8n m\xe3 hoặc tr\xedch xuất dữ liệu"]}},{type:"p",text:{en:"Where we can, we email you the reason and give you a chance to respond. For fraud or an active attack we act first and explain afterwards. If we close an account for a breach, we do not refund the remaining period.",vi:"Khi c\xf3 thể, ch\xfang t\xf4i sẽ gửi email n\xeau l\xfd do v\xe0 cho bạn cơ hội phản hồi. Với h\xe0nh vi gian lận hoặc tấn c\xf4ng đang diễn ra, ch\xfang t\xf4i xử l\xfd trước v\xe0 giải th\xedch sau. Nếu ch\xfang t\xf4i đ\xf3ng t\xe0i khoản v\xec vi phạm, ch\xfang t\xf4i kh\xf4ng ho\xe0n tiền cho phần thời gian c\xf2n lại."}},{type:"p",text:{en:"You can close your account yourself at any time. See the account deletion page.",vi:"Bạn c\xf3 thể tự đ\xf3ng t\xe0i khoản bất cứ l\xfac n\xe0o. Xem trang xo\xe1 t\xe0i khoản."}}]},{id:"availability",title:{en:"Availability",vi:"T\xednh sẵn s\xe0ng của dịch vụ"},blocks:[{type:"p",text:{en:"We do not promise the service will be available without interruption. Servers go down, networks fail, and some countries block VPN traffic. We aim to restore service quickly but we cannot guarantee a particular level of uptime or speed.",vi:"Ch\xfang t\xf4i kh\xf4ng cam kết dịch vụ hoạt động li\xean tục kh\xf4ng gi\xe1n đoạn. M\xe1y chủ c\xf3 thể ngừng, mạng c\xf3 thể lỗi, v\xe0 một số quốc gia chặn lưu lượng VPN. Ch\xfang t\xf4i cố gắng kh\xf4i phục nhanh nhất c\xf3 thể nhưng kh\xf4ng thể bảo đảm một mức thời gian hoạt động hay tốc độ cụ thể."}},{type:"p",text:{en:"A VPN hides your traffic from the network you are on. It does not make you anonymous, and it does not protect you from malware, phishing, or anything you sign in to yourself.",vi:"VPN che lưu lượng của bạn khỏi mạng bạn đang d\xf9ng. VPN kh\xf4ng khiến bạn ẩn danh, v\xe0 kh\xf4ng bảo vệ bạn khỏi m\xe3 độc, lừa đảo, hay những dịch vụ m\xe0 ch\xednh bạn đăng nhập v\xe0o."}}]},{id:"liability",title:{en:"Liability",vi:"Tr\xe1ch nhiệm"},blocks:[{type:"p",text:{en:"The service is provided as is. To the extent the law allows, we are not liable for indirect or consequential loss, and our total liability to you is limited to the amount you paid us in the 12 months before the claim.",vi:"Dịch vụ được cung cấp theo hiện trạng. Trong phạm vi ph\xe1p luật cho ph\xe9p, ch\xfang t\xf4i kh\xf4ng chịu tr\xe1ch nhiệm cho thiệt hại gi\xe1n tiếp hoặc ph\xe1i sinh, v\xe0 tổng tr\xe1ch nhiệm của ch\xfang t\xf4i với bạn giới hạn ở số tiền bạn đ\xe3 thanh to\xe1n cho ch\xfang t\xf4i trong 12 th\xe1ng trước thời điểm ph\xe1t sinh khiếu nại."}},{type:"p",text:{en:"Nothing here limits rights you have under consumer law that cannot be limited by agreement.",vi:"Kh\xf4ng nội dung n\xe0o ở đ\xe2y l\xe0m hạn chế c\xe1c quyền của bạn theo ph\xe1p luật bảo vệ người ti\xeau d\xf9ng m\xe0 kh\xf4ng thể bị hạn chế bằng thoả thuận."}}]},{id:"changes",title:{en:"Changes to these terms",vi:"Thay đổi điều khoản"},blocks:[{type:"p",text:{en:"When we change these terms we update the effective date at the top of the page. For changes that reduce what you get or add obligations, we email registered users before the change takes effect. Continuing to use the service after that date means you accept the new terms.",vi:"Khi thay đổi điều khoản n\xe0y, ch\xfang t\xf4i cập nhật ng\xe0y hiệu lực ở đầu trang. Với c\xe1c thay đổi l\xe0m giảm quyền lợi của bạn hoặc th\xeam nghĩa vụ, ch\xfang t\xf4i gửi email cho người d\xf9ng đ\xe3 đăng k\xfd trước khi thay đổi c\xf3 hiệu lực. Việc tiếp tục sử dụng dịch vụ sau ng\xe0y đ\xf3 được hiểu l\xe0 bạn chấp nhận điều khoản mới."}}]}]}}}]);